// Split contacts into individual items with personalized messages
const data = $input.first().json.body || $input.first().json;

const userName = data.user_name || 'your elder';
const medicineName = data.medicine_name || 'medicine';
const daysRemaining = data.days_remaining || 0;
const stockCount = data.stock_count || 0;
const contacts = data.contacts || [];
const backendUrl = data.backend_url || 'http://localhost:8001';

const items = [];

for (const contact of contacts) {
  let message = '';
  const rel = (contact.relationship || '').toLowerCase();

  if (rel === 'doctor' || rel === 'physician') {
    message = `Dr. ${contact.name}, this is an automated alert from ElderWise health companion.\n\n` +
      `Your patient ${userName}'s ${medicineName} supply is running low — only ${daysRemaining} days remaining (${stockCount} units in stock).\n\n` +
      `A prescription refill may be needed. Please advise at your earliest convenience.`;
  } else {
    message = `Hi ${contact.name}, this is an automated alert from ElderWise.\n\n` +
      `${userName}'s ${medicineName} stock is running low — only ${daysRemaining} days left (${stockCount} units remaining).\n\n` +
      `Please help arrange a refill soon. Thank you for caring! 💙`;
  }

  items.push({
    json: {
      phone: contact.phone,
      name: contact.name,
      relationship: contact.relationship,
      message: message,
      backend_url: backendUrl
    }
  });
}

if (items.length === 0) {
  items.push({
    json: {
      skip: true,
      reason: 'No contacts provided'
    }
  });
}

return items;

// Summarize results
const results = $input.all();
const sent = results.filter(r => r.json.sent === true).length;
const failed = results.length - sent;

return [{
  json: {
    total_contacts: results.length,
    messages_sent: sent,
    messages_failed: failed,
    timestamp: new Date().toISOString()
  }
}];
